# Let me examine the structure more holistically
# Both demos have 6 regions mentioned in the memory

def find_6_rectangular_regions(grid):
    """Find six connected rectangular regions based on flood fill"""
    visited = [[False]*15 for _ in range(15)]
    regions = []

    def bfs(start_pos):
        region_cells = [start_pos]
        sr, sc = start_pos
        queue = [start_pos]
        while queue:
            curr = queue.pop(0)
            cr, cc = curr
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < 15 and 0 <= nc < 15 and not visited[nr][nc]:
                    if grid[nr][nc] == 9:
                        visited[nr][nc] = True
                        region_cells.append((nr, nc))
                        queue.append((nr, nc))
        return sorted(region_cells)

    for r in range(15):
        for c in range(15):
            if grid[r][c] == 9 and not visited[r][c]:
                region = bfs((r,c))
                if region:
                    regions.append(region)
    return regions

